// Generic interactive SLR report. Do not edit for one review.
// Input: window.SLR = { config, contentHtml, records, studies, searchLog, strings, builtOn } (made by build-report.js).
// The content HTML can contain these markers: <div data-widget="NAME"></div> with NAME =
//   prisma | year-chart | study-table | quality-charts | theme-matrix | search-strings | search-log | references
// Citations: <a class="cite" data-id="STUDY_ID"></a>. Inline counts: <span data-count="KEY"></span>
//   KEY = studies | years | meanQuality | screened | weak | group:<groupKey>
(() => {
  const D = window.SLR;
  const C = D.config;
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const byId = Object.fromEntries(D.studies.map(s => [s.id, s]));
  const SVG = 'http://www.w3.org/2000/svg';
  const el = (tag, attrs = {}, parent) => {
    const n = document.createElementNS(SVG, tag);
    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
    if (parent) parent.appendChild(n);
    return n;
  };
  const root = document.documentElement;
  const css = v => getComputedStyle(root).getPropertyValue(v).trim();
  const groups = C.groups || [];
  const groupKey = C.groupBy || null;
  const groupOf = s => (groupKey ? s[groupKey] : '');
  const groupIdx = k => Math.max(0, groups.findIndex(g => g.key === k));
  const groupVar = k => `--series-${(groupIdx(k) % 4) + 1}`;
  const groupChip = k => (groupKey && k ? `<span class="layer-chip s${(groupIdx(k) % 4) + 1}" title="${esc((groups[groupIdx(k)] || {}).label)}">${esc(k)}</span>` : '');
  const threshold = C.qualityThreshold ?? 3.5;
  const borderline = new Set(C.borderline || []);

  // ---------- Page shell ----------
  document.title = C.shortTitle || C.title;
  $('#topbar-title').textContent = C.shortTitle || C.title;
  $('#content').innerHTML = D.contentHtml;
  $('#topnav').innerHTML = $$('#content > section[id]').map(s => {
    const h = $('h2', s);
    return `<a href="#${s.id}">${esc((h ? h.textContent : s.id).replace(/^\d+\.\s*/, '').replace(/\s*\(.*\)$/, ''))}</a>`;
  }).join('');
  $('#foot').innerHTML = `<p>${C.footer ? C.footer + ' ' : ''}Generated by <code>build-report.js</code> on ${esc(D.builtOn)} from <code>records.csv</code>, <code>extraction.csv</code>, <code>quality.csv</code>, <code>references.bib</code> and <code>search-log.csv</code>.</p>`;

  // ---------- Theme toggle ----------
  try { const t = localStorage.getItem('slr-theme'); if (t) root.dataset.theme = t; } catch (e) { /* storage not available */ }
  $('#theme-toggle').addEventListener('click', () => {
    const dark = root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
    root.dataset.theme = dark ? 'light' : 'dark';
    try { localStorage.setItem('slr-theme', root.dataset.theme); } catch (e) { /* ignore */ }
    drawCharts();
  });

  // ---------- Tooltip ----------
  const tip = $('#tooltip');
  const showTip = (html, ev) => {
    tip.innerHTML = html; tip.hidden = false;
    const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
    let x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + w > innerWidth - 8) x = ev.clientX - w - pad;
    if (y + h > innerHeight - 8) y = ev.clientY - h - pad;
    tip.style.left = x + 'px'; tip.style.top = y + 'px';
  };
  const hideTip = () => { tip.hidden = true; };

  // ---------- Record groups (ID prefix -> PRISMA column) ----------
  const P = C.prisma || {};
  const colOf = r => (P.groups || { R: 'database', N: 'database', B: 'other' })[r.id[0]] || 'database';
  const R = D.records;
  const dbRecs = R.filter(r => colOf(r) === 'database');
  const otherRecs = R.filter(r => colOf(r) === 'other');
  const dbScreened = dbRecs.filter(r => r.ta !== 'duplicate');
  const isFT = r => r.ta === 'include' || r.ta === 'uncertain';
  const included = R.filter(r => r.ft === 'include');
  const hits = id => parseInt((D.searchLog.find(s => s.id === id) || {}).results, 10) || 0;
  const searchHits = Object.fromEntries(Object.entries(P.searchIds || {}).map(([k, ids]) => [k, ids.reduce((a, id) => a + hits(id), 0)]));
  const totalHits = Object.values(searchHits).reduce((a, b) => a + b, 0);
  const crit = reason => (reason || '').split(':')[0];
  const countBy = (rows, f) => rows.reduce((m, r) => { const k = f(r); m[k] = (m[k] || 0) + 1; return m; }, {});

  // ---------- Hero ----------
  const years = D.studies.map(s => +s.year);
  const meanQ = D.studies.length ? (D.studies.reduce((a, s) => a + s.total, 0) / D.studies.length).toFixed(2) : '0';
  const auto = {
    included: D.studies.length, screened: dbScreened.length + otherRecs.length,
    fulltexts: R.filter(isFT).length, weak: D.studies.filter(s => s.evidence === 'weak').length,
  };
  const tileVal = v => (typeof v === 'string' && v.startsWith('auto:') ? auto[v.slice(5)] : v);
  $('#hero').innerHTML = `${C.eyebrow ? `<p class="eyebrow">${esc(C.eyebrow)}</p>` : ''}<h1>${esc(C.title)}</h1>
    ${C.lede ? `<p class="lede">${C.lede}</p>` : ''}
    <div class="tiles">${(C.tiles || []).map(t => `<div class="tile"><div class="val">${esc(tileVal(t.value))}</div><div class="lbl">${esc(t.label)}</div></div>`).join('')}</div>
    ${C.mainResult ? `<div class="callout"><strong>Main result.</strong> ${C.mainResult}</div>` : ''}`;

  const counts = {
    studies: D.studies.length, years: years.length ? `${Math.min(...years)} to ${Math.max(...years)}` : '',
    meanQuality: meanQ, screened: auto.screened, weak: auto.weak,
  };
  groups.forEach(g => { counts['group:' + g.key] = D.studies.filter(s => groupOf(s) === g.key).length; });
  $$('[data-count]').forEach(n => { n.textContent = counts[n.dataset.count] ?? `[unknown count ${n.dataset.count}]`; });

  // ---------- Citations ----------
  const bindCites = scope => $$('a.cite', scope).forEach(a => {
    const s = byId[a.dataset.id];
    if (!s) { a.textContent = '[missing ' + a.dataset.id + ']'; return; }
    a.textContent = s.cite;
    a.href = '#ref-' + s.id;
    a.onmouseenter = ev => showTip(`<b>${esc(s.title)}</b>${esc(s.venue)} · quality ${s.total}/${s.quality.length}${s.evidence === 'weak' ? ' (weak)' : ''}`, ev);
    a.onmouseleave = hideTip;
  });

  // ---------- Widgets ----------
  const W = {};

  W['search-strings'] = host => {
    host.innerHTML = `<details class="disclosure"><summary>Show the search strings</summary>${Object.entries(D.strings).map(([k, v]) => `<h4>${esc(k)}</h4><pre class="code">${esc(v)}</pre>`).join('')}</details>`;
  };

  W['search-log'] = host => {
    host.innerHTML = `<details class="disclosure"><summary>Show the search log (${D.searchLog.length} searches)</summary><div class="table-wrap"><table class="data compact">
      <thead><tr><th>ID</th><th>Date</th><th>Step</th><th>Purpose</th><th>Limits</th><th class="num">Results</th></tr></thead><tbody>${D.searchLog.map(s =>
      `<tr><td>${esc(s.id)}</td><td>${esc(s.date)}</td><td>${esc(s.step)}</td><td>${esc(s.purpose)}<br><code>${esc(s.query.length > 160 ? s.query.slice(0, 160) + '…' : s.query)}</code></td><td>${esc(s.limits)}</td><td class="num">${esc(s.results)}</td></tr>`).join('')}</tbody></table></div></details>`;
  };

  W.prisma = host => {
    host.innerHTML = `<p class="hint">Select a box to see the records and the reasons for exclusion.</p><div class="prisma-layout"><div class="prisma" aria-label="PRISMA flow diagram"></div><aside class="panel" aria-live="polite"><p class="muted">Select a box in the diagram.</p></aside></div>`;
    const pr = $('.prisma', host), panel = $('.panel', host);
    const recItem = r => `<li><b>${esc(r.id)}</b> ${esc(r.title)} <span class="muted">(${esc(r.year)}, ${esc(r.type)})</span><span class="reason">${esc(r.ftReason || r.taReason)}</span></li>`;
    const critBars = rows => {
      const c = Object.entries(countBy(rows, r => crit(r.ft === 'exclude' ? r.ftReason : r.taReason))).sort((a, b) => b[1] - a[1]);
      const max = Math.max(...c.map(x => x[1]), 1);
      return '<div class="bars-mini">' + c.map(([k, v]) => `<span>${esc(k)}</span><span class="bar" style="width:${(100 * v / max).toFixed(1)}%"></span><span>${v}</span>`).join('') + '</div>';
    };
    const exList = (rows, stage) => `<h4>Excluded at ${stage} (${rows.length})</h4>${critBars(rows)}<ul class="reclist">${rows.map(recItem).join('')}</ul>`;
    const dups = dbRecs.filter(r => r.ta === 'duplicate').length;
    const hitText = Object.entries(searchHits).map(([k, v]) => `${k} ${v}`).join(' · ');
    const boxes = [
      { stage: 'Identification', col: 1, n: totalHits, title: `Records from ${C.database || 'the database'}`, sub: hitText,
        panel: () => `<h4>Identification (database)</h4><p>${Object.entries(P.searchIds || {}).map(([k, ids]) => `${esc(k)}: ${ids.join(' + ')} = ${searchHits[k]} results.`).join('<br>')}</p><p>Duplicates marked in the records: ${dups}.</p>${P.removedNote || ''}` },
      { stage: 'Identification', col: 2, n: otherRecs.length, title: P.otherLabel || 'Records from backward snowballing', sub: P.otherSub || 'reference lists',
        panel: () => `<h4>${esc(P.otherLabel || 'Snowballing records')}</h4><ul class="reclist">${otherRecs.map(recItem).join('')}</ul>` },
      { stage: 'Screening', col: 1, n: dbScreened.length, title: 'Title and abstract screening', sub: `excluded ${dbScreened.filter(r => r.ta === 'exclude').length}`,
        panel: () => exList(dbScreened.filter(r => r.ta === 'exclude'), 'title and abstract') },
      { stage: 'Screening', col: 2, n: otherRecs.length, title: 'Title and abstract screening', sub: `excluded ${otherRecs.filter(r => r.ta === 'exclude').length}`,
        panel: () => exList(otherRecs.filter(r => r.ta === 'exclude'), 'title and abstract') },
      { stage: 'Eligibility', col: 1, n: dbScreened.filter(isFT).length, title: 'Full texts assessed', sub: `not retrieved ${dbScreened.filter(r => r.ft === 'not retrieved').length} · excluded ${dbScreened.filter(r => r.ft === 'exclude').length}`,
        panel: () => exList(dbScreened.filter(r => r.ft === 'exclude'), 'full text') },
      { stage: 'Eligibility', col: 2, n: otherRecs.filter(isFT).length, title: 'Full texts assessed', sub: `not retrieved ${otherRecs.filter(r => r.ft === 'not retrieved').length} · excluded ${otherRecs.filter(r => r.ft === 'exclude').length}`,
        panel: () => exList(otherRecs.filter(r => r.ft === 'exclude'), 'full text') },
      { stage: 'Included', col: 0, n: included.length, title: 'Studies included in the review', cls: 'included',
        sub: Object.entries(countBy(included, r => (P.prefixLabels || { R: 'main', N: 'supplementary', B: 'snowballing' })[r.id[0]] || r.id[0])).map(([k, v]) => `${k} ${v}`).join(' · '),
        panel: () => `<h4>Included studies (${included.length})</h4><ul class="reclist">${included.map(r => `<li><b>${esc(byId[r.id] ? byId[r.id].cite : r.id)}</b> ${esc(r.title)}<span class="reason">${r.layer ? 'Group ' + esc(r.layer) + ' · ' : ''}${esc(r.ftReason)}</span></li>`).join('')}</ul>` },
    ];
    pr.innerHTML = '<div></div><div class="colhead">Database search</div><div class="colhead">Other methods</div>';
    for (const stage of ['Identification', 'Screening', 'Eligibility', 'Included']) {
      pr.insertAdjacentHTML('beforeend', `<div class="stage">${stage}</div>`);
      for (const b of boxes.filter(x => x.stage === stage)) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'pbox' + (b.cls ? ' ' + b.cls : '') + (b.col === 0 ? ' span2' : '');
        btn.innerHTML = `<span class="n">${b.n}</span>${esc(b.title)}<span class="sub">${esc(b.sub)}</span>`;
        btn.addEventListener('click', () => {
          $$('.pbox', pr).forEach(x => x.classList.remove('active'));
          btn.classList.add('active');
          panel.innerHTML = b.panel();
        });
        pr.appendChild(btn);
      }
    }
  };

  // Charts are drawn again when the theme changes, so they keep the reference to their host.
  const charts = [];

  W['year-chart'] = host => {
    host.innerHTML = `<figure class="chart-card"><figcaption>${host.dataset.caption || '<strong>Figure.</strong> Included studies by year of publication'}</figcaption><div class="legend"></div><div class="chart" role="img" aria-label="Bar chart of included studies by year"></div></figure>`;
    const draw = () => {
      const box = $('.chart', host); box.innerHTML = '';
      if (!years.length) return;
      const ys = []; for (let y = Math.min(...years); y <= Math.max(...years); y++) ys.push(y);
      const Wd = 720, H = 220, m = { t: 12, r: 8, b: 26, l: 28 };
      const svg = el('svg', { viewBox: `0 0 ${Wd} ${H}` }, box);
      const yMax = Math.max(...ys.map(y => D.studies.filter(s => +s.year === y).length), 1);
      const sy = v => H - m.b - (v / yMax) * (H - m.t - m.b);
      for (let v = 0; v <= yMax; v++) { el('line', { x1: m.l, x2: Wd - m.r, y1: sy(v), y2: sy(v), class: v ? 'grid' : 'axis' }, svg); el('text', { x: m.l - 8, y: sy(v) + 4, 'text-anchor': 'end' }, svg).textContent = v; }
      const bw = (Wd - m.l - m.r) / ys.length, barW = Math.min(28, bw * 0.6);
      const order = groupKey && groups.length ? groups.map(g => g.key) : [''];
      ys.forEach((y, i) => {
        const x = m.l + i * bw + (bw - barW) / 2;
        const list = D.studies.filter(s => +s.year === y);
        let acc = 0;
        for (const g of order) {
          const n = list.filter(s => !groupKey || groupOf(s) === g).length;
          if (!n) continue;
          const gap = acc ? 2 : 0, y0 = sy(acc) - gap, y1 = sy(acc + n), top = acc + n === list.length, r = top ? 4 : 0;
          const p = `M${x},${y0} V${y1 + r} ${r ? `Q${x},${y1} ${x + r},${y1} H${x + barW - r} Q${x + barW},${y1} ${x + barW},${y1 + r}` : `H${x + barW}`} V${y0} Z`;
          if (y0 - y1 > 0) el('path', { d: p, fill: css(g ? groupVar(g) : '--series-1'), class: 'mark' }, svg);
          acc += n;
        }
        if (i % (ys.length > 10 ? 2 : 1) === 0 || list.length) el('text', { x: x + barW / 2, y: H - 8, 'text-anchor': 'middle' }, svg).textContent = y;
        const hit = el('rect', { x: m.l + i * bw, y: m.t, width: bw, height: H - m.t - m.b, class: 'hit' }, svg);
        hit.addEventListener('mousemove', ev => showTip(`<b>${y}: ${list.length} ${list.length === 1 ? 'study' : 'studies'}</b>${list.map(s => `${esc(s.cite)}${groupKey ? ' · ' + esc(groupOf(s)) : ''}`).join('<br>') || 'none'}`, ev));
        hit.addEventListener('mouseleave', hideTip);
      });
      $('.legend', host).innerHTML = groupKey && groups.length > 1
        ? groups.map(g => `<span><span class="sw" style="background:var(${groupVar(g.key)})"></span>${esc(g.label)} (${counts['group:' + g.key]})</span>`).join('') : '';
    };
    charts.push(draw);
  };

  W['quality-charts'] = host => {
    const qn = C.qualityQuestions || (D.studies[0] ? D.studies[0].quality.map((_, i) => 'Q' + (i + 1)) : []);
    const nQ = qn.length;
    host.innerHTML = `<div class="two-col charts">
      <figure class="chart-card"><figcaption><strong>${esc(host.dataset.figA || 'Figure.')}</strong> Answers for each quality question</figcaption><div class="legend q-legend"></div><div class="chart q-chart" role="img" aria-label="Stacked bars of yes, partially and no for each quality question"></div></figure>
      <figure class="chart-card"><figcaption><strong>${esc(host.dataset.figB || 'Figure.')}</strong> Total quality score of each study (line: ${threshold}, weak below)</figcaption><div class="chart s-chart" role="img" aria-label="Bars of the total quality score of each study"></div></figure></div>`;
    const cats = [[1, 'yes', '--ord-yes'], [0.5, 'partially', '--ord-partial'], [0, 'no', '--ord-no']];
    charts.push(() => {
      const box = $('.q-chart', host); box.innerHTML = '';
      const Wd = 420, rowH = 30, m = { t: 6, r: 10, b: 22, l: 128 }, H = m.t + m.b + rowH * nQ;
      const svg = el('svg', { viewBox: `0 0 ${Wd} ${H}` }, box);
      const n = D.studies.length, sx = v => m.l + (v / n) * (Wd - m.l - m.r);
      [0, Math.round(n / 2), n].forEach(v => { el('line', { x1: sx(v), x2: sx(v), y1: m.t, y2: H - m.b, class: v ? 'grid' : 'axis' }, svg); el('text', { x: sx(v), y: H - 6, 'text-anchor': 'middle' }, svg).textContent = v; });
      qn.forEach((nm, qi) => {
        const y = m.t + qi * rowH + 6, h = rowH - 12;
        el('text', { x: m.l - 8, y: y + h / 2 + 4, 'text-anchor': 'end', class: 'label-strong' }, svg).textContent = nm;
        let acc = 0;
        cats.forEach(([sc, lab, col]) => {
          const list = D.studies.filter(s => s.quality[qi] && s.quality[qi].score === sc);
          if (!list.length) return;
          const x0 = sx(acc) + (acc ? 2 : 0), x1 = sx(acc + list.length), last = acc + list.length === n, r = last ? 4 : 0, w = x1 - x0;
          const p = `M${x0},${y} H${x1 - r} ${r ? `Q${x1},${y} ${x1},${y + r} V${y + h - r} Q${x1},${y + h} ${x1 - r},${y + h}` : `V${y + h}`} H${x0} Z`;
          if (w > 0) el('path', { d: p, fill: css(col), class: 'mark' }, svg);
          const hit = el('rect', { x: x0, y: y - 4, width: Math.max(w, 6), height: h + 8, class: 'hit' }, svg);
          hit.addEventListener('mousemove', ev => showTip(`<b>${esc(nm)}: ${lab} (${list.length})</b>${list.map(s => esc(s.cite)).join('<br>')}`, ev));
          hit.addEventListener('mouseleave', hideTip);
          acc += list.length;
        });
      });
      $('.q-legend', host).innerHTML = cats.map(([, lab, col]) => `<span><span class="sw" style="background:var(${col})"></span>${lab}</span>`).join('');
    });
    charts.push(() => {
      const box = $('.s-chart', host); box.innerHTML = '';
      const list = [...D.studies].sort((a, b) => b.total - a.total || a.cite.localeCompare(b.cite));
      const Wd = 420, rowH = 20, m = { t: 6, r: 30, b: 22, l: 150 }, H = m.t + m.b + rowH * list.length;
      const svg = el('svg', { viewBox: `0 0 ${Wd} ${H}` }, box);
      const sx = v => m.l + (v / nQ) * (Wd - m.l - m.r);
      [0, threshold, nQ].forEach(v => { el('line', { x1: sx(v), x2: sx(v), y1: m.t, y2: H - m.b, class: v === 0 ? 'axis' : 'grid' }, svg); el('text', { x: sx(v), y: H - 6, 'text-anchor': 'middle' }, svg).textContent = v; });
      el('line', { x1: sx(threshold), x2: sx(threshold), y1: m.t, y2: H - m.b, stroke: css('--weak'), 'stroke-dasharray': '3 3', 'stroke-width': 1.5 }, svg);
      list.forEach((s, i) => {
        const y = m.t + i * rowH + 4, h = rowH - 8, x1 = sx(s.total), r = Math.min(4, h / 2);
        el('text', { x: m.l - 8, y: y + h / 2 + 4, 'text-anchor': 'end', class: 'label-strong' }, svg).textContent = s.cite;
        if (s.total > 0) el('path', { d: `M${m.l},${y} H${x1 - r} Q${x1},${y} ${x1},${y + r} V${y + h - r} Q${x1},${y + h} ${x1 - r},${y + h} H${m.l} Z`, fill: css('--accent'), class: 'mark' }, svg);
        el('text', { x: x1 + 4, y: y + h / 2 + 4 }, svg).textContent = s.total;
        const hit = el('rect', { x: 0, y: y - 4, width: Wd, height: rowH, class: 'hit' }, svg);
        hit.style.cursor = 'pointer';
        hit.addEventListener('mousemove', ev => showTip(`<b>${esc(s.cite)}: ${s.total}/${nQ} (${s.evidence})</b>${s.quality.map((q, k) => `Q${k + 1} ${q.score}`).join(' · ')}<br><span class="muted">Select to see the details</span>`, ev));
        hit.addEventListener('mouseleave', hideTip);
        hit.addEventListener('click', () => openStudy(s.id));
      });
    });
  };

  W['study-table'] = host => {
    const cols = C.tableColumns || [
      { key: 'cite', label: 'Study' }, { key: 'group', label: 'Group' }, { key: 'study_type', label: 'Type' },
      { key: 'n_participants', label: 'Participants' }, { key: 'comparison', label: 'Comparison' }, { key: 'total', label: 'Quality' }];
    const types = [...new Set(D.studies.map(s => s.study_type).filter(Boolean))].sort();
    host.innerHTML = `<div class="filters" role="group" aria-label="Filter the studies">
      ${groupKey && groups.length ? `<label>${esc(C.groupLabel || 'Group')}<select class="f-group"><option value="">All</option>${groups.map(g => `<option value="${esc(g.key)}">${esc(g.label)}</option>`).join('')}</select></label>` : ''}
      <label>Study type<select class="f-type"><option value="">All</option>${types.map(t => `<option>${esc(t)}</option>`).join('')}</select></label>
      <label>Evidence<select class="f-evidence"><option value="">All</option><option value="adequate">Adequate</option><option value="weak">Weak</option></select></label>
      <label class="grow">Search<input class="f-text" type="search" placeholder="Title, result…"></label></div>
      <p class="hint">Select a row to see all extracted data and the quality assessment of the study.</p>
      <div class="table-wrap"><table class="data studies"><thead><tr>${cols.map(c => `<th data-sort="${esc(c.key)}" scope="col"${c.key === 'total' ? ' class="num"' : ''}>${esc(c.key === 'group' ? (C.groupLabel || c.label) : c.label)}</th>`).join('')}</tr></thead><tbody></tbody></table></div>
      <p class="muted small count"></p>`;
    let sortKey = 'year', sortDir = 1;
    const short = v => esc(String(v ?? '').replace(/\s*\(.*$/, ''));
    const cell = (s, c) => {
      if (c.key === 'cite') return `<td><b>${esc(s.cite)}</b>${borderline.has(s.id) ? '<span class="borderline-badge">borderline</span>' : ''}<br><span class="muted small">${esc(s.title)}</span></td>`;
      if (c.key === 'group') return `<td>${groupChip(groupOf(s))}</td>`;
      if (c.key === 'total') return `<td class="num">${s.total}${s.evidence === 'weak' ? '<span class="weak-badge">weak</span>' : ''}</td>`;
      return `<td>${short(s[c.key])}</td>`;
    };
    const render = () => {
      const fg = $('.f-group', host) ? $('.f-group', host).value : '', ft = $('.f-type', host).value, fe = $('.f-evidence', host).value, q = $('.f-text', host).value.trim().toLowerCase();
      const rows = D.studies.filter(s => (!fg || groupOf(s) === fg) && (!ft || s.study_type === ft) && (!fe || s.evidence === fe) &&
        (!q || [s.title, s.cite, s.result, s.authors, ...cols.map(c => s[c.key])].join(' ').toLowerCase().includes(q)));
      rows.sort((a, b) => {
        const k = sortKey === 'cite' ? 'year' : sortKey === 'group' ? groupKey : sortKey;
        const va = a[k], vb = b[k];
        const c = typeof va === 'number' ? va - vb : String(va).localeCompare(String(vb), undefined, { numeric: true });
        return c * sortDir || a.cite.localeCompare(b.cite);
      });
      $('tbody', host).innerHTML = rows.map(s => `<tr tabindex="0" data-id="${s.id}">${cols.map(c => cell(s, c)).join('')}</tr>`).join('');
      $('.count', host).textContent = `${rows.length} of ${D.studies.length} studies shown`;
      $$('tbody tr', host).forEach(tr => {
        tr.addEventListener('click', () => openStudy(tr.dataset.id));
        tr.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openStudy(tr.dataset.id); } });
      });
    };
    $$('select, input', host).forEach(i => i.addEventListener('input', render));
    $$('th[data-sort]', host).forEach(th => th.addEventListener('click', () => {
      const k = th.dataset.sort;
      sortDir = sortKey === k ? -sortDir : 1; sortKey = k;
      $$('th', host).forEach(x => x.classList.remove('sorted-asc', 'sorted-desc'));
      th.classList.add(sortDir === 1 ? 'sorted-asc' : 'sorted-desc');
      render();
    }));
    render();
  };

  W['theme-matrix'] = host => {
    const themes = C.themes || [];
    const colIds = C.matrixColumns || [...D.studies].sort((a, b) => themes.filter(t => t.studies.includes(b.id)).length - themes.filter(t => t.studies.includes(a.id)).length).map(s => s.id);
    host.innerHTML = `<div class="matrix-layout"><div class="table-wrap"><table class="matrix"></table></div><aside class="panel" aria-live="polite"></aside></div>`;
    const mx = $('table', host), panel = $('.panel', host);
    mx.innerHTML = `<thead><tr><th></th>${colIds.map(c => `<th><button type="button" data-study="${c}" title="${esc(byId[c].title)}">${esc(byId[c].cite)}</button></th>`).join('')}<th></th></tr></thead>
      <tbody>${themes.map(t => `<tr><th><button type="button" data-theme="${t.id}">${esc(t.id)} ${esc(t.name)}</button></th>${colIds.map(c => {
        const on = t.studies.includes(c);
        return `<td class="cell${on ? ' on' : ''}${on && byId[c].evidence === 'weak' ? ' weakcell' : ''}" data-theme="${t.id}" data-study="${c}"></td>`;
      }).join('')}<td class="count">${t.studies.length}</td></tr>`).join('')}</tbody>`;
    const focus = (pred, html) => {
      mx.classList.add('focus');
      $$('td.cell', mx).forEach(td => td.classList.toggle('hl', pred(td.dataset.theme, td.dataset.study)));
      panel.innerHTML = html;
      bindCites(panel);
    };
    const links = ids => ids.map(id => `<a class="cite" data-id="${id}"></a>${byId[id] && byId[id].evidence === 'weak' ? ' (weak)' : ''}`).join('; ');
    const showTheme = id => {
      const t = themes.find(x => x.id === id);
      $$('button', mx).forEach(b => b.classList.toggle('active', b.dataset.theme === id));
      focus(th => th === id, `<h4>${esc(t.id)} ${esc(t.name)}${t.strength ? `<span class="strength">${esc(t.strength)}</span>` : ''}</h4><p>${t.text}</p><p class="small"><b>Studies (${t.studies.length}):</b> ${links(t.studies)}</p>`);
    };
    $$('button[data-theme]', mx).forEach(b => b.addEventListener('click', () => showTheme(b.dataset.theme)));
    $$('button[data-study]', mx).forEach(b => b.addEventListener('click', () => {
      const id = b.dataset.study, s = byId[id];
      $$('button', mx).forEach(x => x.classList.toggle('active', x === b));
      const ts = themes.filter(t => t.studies.includes(id));
      focus((th, st) => st === id, `<h4>${esc(s.cite)}</h4><p class="small muted">${esc(s.title)}</p><p><b>Themes:</b> ${ts.map(t => `${esc(t.id)} ${esc(t.name)}`).join('; ') || 'none'}</p><p class="small">${esc(s.result)}</p><button class="btn-ghost" type="button" data-open="${id}">Show all data of the study</button>`);
      $('[data-open]', panel).addEventListener('click', () => openStudy(id));
    }));
    $$('td.cell', mx).forEach(td => {
      td.addEventListener('mousemove', ev => {
        const t = themes.find(x => x.id === td.dataset.theme), s = byId[td.dataset.study];
        showTip(`<b>${esc(s.cite)} · ${esc(t.id)}</b>${td.classList.contains('on') ? 'Supports this theme' : 'No support'}${s.evidence === 'weak' ? ' (weak evidence)' : ''}`, ev);
      });
      td.addEventListener('mouseleave', hideTip);
    });
    if (themes.length) showTheme(themes[0].id);
  };

  W.references = host => {
    const list = [...D.studies].sort((a, b) => a.bib.author.localeCompare(b.bib.author) || a.year - b.year);
    host.innerHTML = `<ol class="refs">${list.map(s => {
      const b = s.bib;
      const authors = b.author.split(' and ').map(a => { const [l, f] = a.split(', '); return f ? `${l}, ${f.split(/[\s-]+/).filter(Boolean).map(x => x[0] + '.').join(' ')}` : a; }).join(', ');
      const pages = (b.pages || '').replace('--', '–');
      const where = b.journal ? `${b.journal}${b.volume ? ' ' + b.volume : ''}${b.number ? `(${b.number})` : ''}${pages ? ', ' + pages : ''}` : `In ${b.booktitle || ''}${b.series ? ` (${b.series})` : ''}${pages ? ', ' + pages : ''}`;
      return `<li id="ref-${s.id}">${esc(authors)} (${esc(b.year)}). ${esc(b.title)}. ${esc(where)}. ${esc(b.publisher ? 'ACM' : '')} <a class="ext" href="https://doi.org/${esc(b.doi)}">doi:${esc(b.doi)}</a> <span class="muted small">[${s.id}]</span></li>`;
    }).join('')}</ol>`;
  };

  // ---------- Study dialog ----------
  const fieldLabels = C.fieldLabels || {};
  const hidden = new Set(['study_id', 'id', 'cite', 'title', 'bib', 'quality', 'total', 'percent', 'evidence', 'authors', 'year']);
  const qNames = C.qualityQuestions || [];
  const pretty = k => fieldLabels[k] || k.replace(/_/g, ' ').replace(/^\w/, c => c.toUpperCase());
  function openStudy(id) {
    const s = byId[id];
    $('#dlg-title').innerHTML = `${esc(s.cite)} · ${esc(s.title)}`;
    const keys = Object.keys(s).filter(k => !hidden.has(k) && typeof s[k] !== 'object');
    $('#dlg-body').innerHTML = `<p class="muted">${esc(s.authors)}</p>
      <dl>${keys.map(k => `<dt>${esc(pretty(k))}</dt><dd>${k === 'doi' ? `<a class="ext" href="https://doi.org/${esc(s.doi)}">${esc(s.doi)}</a>` : esc(s[k])}</dd>`).join('')}</dl>
      <h4>Quality assessment: ${s.total}/${s.quality.length} (${esc(s.evidence)})</h4>
      ${s.quality.map((q, k) => `<div class="qrow"><b>Q${k + 1}</b><span class="qdot ${q.score === 1 ? 's1' : q.score === 0.5 ? 's05' : 's0'}">${q.score === 1 ? 'yes' : q.score === 0.5 ? 'part.' : 'no'}</span><span>${qNames[k] ? `<b>${esc(qNames[k].replace(/^Q\d+\s*/, ''))}.</b> ` : ''}${esc(q.reason)}</span></div>`).join('')}`;
    const dlg = $('#study-dialog');
    if (typeof dlg.showModal === 'function') dlg.showModal(); else dlg.setAttribute('open', '');
  }
  $('#study-dialog').addEventListener('click', e => { if (e.target.id === 'study-dialog') e.target.close(); });

  // ---------- Mount ----------
  $$('[data-widget]').forEach(host => {
    const f = W[host.dataset.widget];
    if (f) f(host); else host.innerHTML = `<p class="weak-badge">Unknown widget: ${esc(host.dataset.widget)}</p>`;
  });
  function drawCharts() { charts.forEach(f => f()); }
  drawCharts();
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', drawCharts);
  bindCites(document);
})();
